const SIZE = 1000;
const ART = 500;
const OFFSET = 250;

let viewScale;
let layoutSeed;

function setup() {
  viewScale = min(windowWidth, windowHeight) / SIZE;
  viewScale = min(viewScale, 1);

  createCanvas(SIZE * viewScale, SIZE * viewScale);

  noLoop();
  generate();
}

function draw() {
  // Artwork is generated by generate()
}

function generate() {
  // NEW layout every generation
  layoutSeed = random(100000);

  randomSeed(layoutSeed);
  noiseSeed(layoutSeed);

  background(0);
  noStroke();

  push();

  translate(OFFSET * viewScale, OFFSET * viewScale);

  scale(viewScale);

  const gridSize = 10;
  const spacing = 25;
  const amplitude = 100;
  const waveDetail = 60;
  const artRange = 500;

  for (let gx = -gridSize; gx <= gridSize; gx++) {
    for (let gy = -gridSize; gy <= gridSize; gy++) {
      const px = gx * spacing;
      const py = gy * spacing;

      if (abs(px) > artRange / 2 || abs(py) > artRange / 2) {
        continue;
      }

      push();

      translate(px + artRange / 2, py + artRange / 2);

      const waveOffset = dist(0, 0, gx, gy) * 0.15;

      const scaleVal = map(noise(gx * 0.1, gy * 0.1), 0, 1, 0.4, 1.2);

      fill(random(155, 255), random(155, 255), random(155, 255));

      beginShape();

      for (let i = 0; i < waveDetail; i++) {
        const a = (TWO_PI * i) / waveDetail;

        const r =
          amplitude *
          scaleVal *
          sin(a * 3 + waveOffset) *
          cos(a * 2 - waveOffset * 10) *
          0.5;

        vertex(cos(a) * r * 0.5, sin(a) * r * 0.5);
      }

      endShape(CLOSE);
      pop();
    }
  }

  pop();
}

function mousePressed() {
  generate();
}

function windowResized() {
  viewScale = min(windowWidth, windowHeight) / SIZE;
  viewScale = min(viewScale, 1);

  resizeCanvas(SIZE * viewScale, SIZE * viewScale);

  generate();
}
